import React, { useState, useEffect, useContext } from 'react';
import { Alert } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { loginUserValidate } from './operation';
import { FaCheck, FaEye, FaEyeSlash, FaGraduationCap, FaLock, FaShieldAlt, FaUserAlt } from 'react-icons/fa';
import { emailValidation } from '../../services/commonUtills/FormValidations';
import { AuthContext } from '../../App';

const initialState = {
  emlid: '',
  pswrd: '',
};

function Login() {
  const { dispatchAuth } = useContext(AuthContext);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [alertShow, setAlertShow] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');
  const [alertVarient, setAlertVarient] = useState('');
  const [showPassword, setShowPassword] = useState(true);
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [loginMethod, setLoginMethod] = useState('password'); // password or otp
  const navigate = useNavigate();

  useEffect(() => {
    dispatchAuth({ type: 'LOGOUT' });
  }, [dispatchAuth]);

  const handleChange = (e) => {
    const { id, value } = e.target;
    if (id === 'email') {
      const normalizedEmail = value.toLowerCase();
      setEmail(normalizedEmail);
      setEmailError('');
    } else if (id === 'pswrd') {
      setPassword(value);
      setPasswordError('');
    }
  };

  const validateData = () => {
    let is_valid = true;
    if (!email) {
      setEmailError('Please Enter Email or Mobile');
      is_valid = false;
    } else if (!emailValidation(email) && !/^[0-9]{10}$/.test(email)) {
      setEmailError('Please Enter Valid Email or 10-digit Mobile');
      is_valid = false;
    }
    if (!password) {
      setPasswordError('Please Enter Password');
      is_valid = false;
    }
    return is_valid;
  };

  const handleSubmit = () => {
    if (validateData()) {
      setIsLoading(true);
      loginAuthentication();
    }
  };

  const loginAuthentication = async () => {
    const obj = { ...initialState, emlid: email, pswrd: password };
    const res = await loginUserValidate(obj);

    if (res && res.status === 'success') {
      setAlertShow(true);
      setAlertMessage('Logged In Successfully');
      setAlertVarient('success');
      hideMessage();
      const sessions = Array.isArray(res.payload) ? res.payload : [res.payload];
      const validSessions = sessions.filter(Boolean);
      const userData = validSessions[0];
      dispatchAuth({
        type: 'LOGIN',
        payload: {
          user: userData,
          studentProfiles:
            validSessions.length > 1 && validSessions.every((item) => String(item.typ || '').toUpperCase() === 'STUDENT')
              ? validSessions
              : [],
        },
      });
      navigate(validSessions.length > 1 ? '/select-student' : '/dashboard');
    } else {
      setAlertShow(true);
      setAlertMessage(
        res?.error?.message || 'Please Enter Valid Details'
      );
      setAlertVarient('danger');
      hideMessage();
      setIsLoading(false);
    }
  };

  const hideMessage = () => {
    setTimeout(() => {
      setAlertShow(false);
      setAlertMessage('');
      setAlertVarient('');
    }, 5000);
  };

  const showHidePassword = () => setShowPassword(!showPassword);

  const loginEnter = (e) => {
    if (e.key === 'Enter') {
      handleSubmit();
    }
  };

  return (
    <>
      <Alert
        className="notification"
        variant={alertVarient}
        show={alertShow}
        onClose={() => setAlertShow(false)}
        dismissible
        style={{
          position: 'fixed',
          top: '20px',
          right: '20px',
          zIndex: 9999,
          boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
        }}
      >
        {alertMessage}
      </Alert>

      <div className="login-container-new">
        <style>{`
          .login-container-new {
            position: relative;
            display: flex;
            min-height: 100vh;
            width: 100%;
            background: linear-gradient(180deg, #eef4f9 0%, #f8fafc 100%);
            font-family: 'Inter', sans-serif;
            overflow: hidden;
          }
          .login-container-new:before,
          .login-container-new:after {
            content: '';
            position: absolute;
            width: 40%;
            height: 160px;
            left: -15%;
            border-top: 5px solid #1f62b8;
            border-radius: 50% 50% 0 0;
            transform: rotate(-14deg);
            opacity: 0.95;
          }
          .login-container-new:before {
            top: -34px;
            background: linear-gradient(135deg, #1a2f84 0%, #1c4dba 100%);
          }
          .login-container-new:after {
            content: '';
            width: 40%;
            height: 160px;
            left: auto;
            right: -16%;
            top: -34px;
            transform: rotate(28deg);
            background: linear-gradient(135deg, #102c7e 0%, #244fca 100%);
          }
          .login-page-skyline {
            pointer-events: none;
            position: absolute;
            bottom: -38px;
            left: 0;
            right: 0;
            height: 210px;
            background-image: linear-gradient(180deg, transparent 0%, rgba(120, 169, 255, 0.075) 100%), repeating-linear-gradient(90deg, transparent 0 24px, rgba(30, 64, 175, 0.12) 24px 25px), linear-gradient(180deg, transparent 0%, #e2edf4 80%, #cadbe7 100%);
            clip-path: polygon(0 28%, 0 100%, 100% 100%, 100% 18%, 88% 18%, 88% 100%, 76% 100%, 76% 22%, 64% 22%, 64% 100%, 52% 100%, 52% 30%, 42% 30%, 42% 100%, 30% 100%, 30% 20%, 18% 20%, 18% 100%, 0 100%);
            opacity: 0.88;
          }
          .login-page-skyline:before {
            content: '';
            position: absolute;
            inset: -6px;
            border-top: 1px solid rgba(30, 64, 175, 0.7);
            border-bottom: 1px solid rgba(30, 64, 175, 0.7);
          }
          .login-left-panel-new {
            display: none;
          }
          .login-right-panel-new {
            flex: 1;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 2rem;
            position: relative;
            z-index: 2;
          }
          .login-auth-shell {
            width: min(100%, 820px);
            min-height: 620px;
            background: rgba(255,255,255,0.92);
            border-radius: 18px;
            border: 1px solid rgba(255,255,255,0.8);
            box-shadow: 0 20px 55px rgba(63, 91, 151, 0.16);
            padding: 78px 96px 44px;
            position: relative;
            display: flex;
            flex-direction: column;
            justify-content: flex-start;
          }
          .login-auth-shell:before {
            content: '';
            position: absolute;
            top: -8%;
            left: 12%;
            right: 12%;
            height: 76px;
            border-top: 2px solid #b3c9ff;
            border-radius: 50%;
            background: transparent;
          }
          .login-auth-shell:after {
            content: '';
            position: absolute;
            bottom: -1px;
            left: 0;
            right: 0;
            height: 34px;
            background: linear-gradient(180deg, rgba(224, 239, 255, 0.36), rgba(255,255,255,0));
            border-bottom-left-radius: 18px;
            border-bottom-right-radius: 18px;
            opacity: 0.85;
          }
          .login-logo {
            display: flex;
            justify-content: center;
            align-items: center;
            margin-bottom: 20px;
          }
          .login-logo-core {
            width: 150px;
            height: 150px;
            border-radius: 50%;
            background: radial-gradient(#fbfaff, #b0d2ff);
            border: 4px solid #d6eaff;
            box-shadow: inset 0 0 0 6px #f8fbff, 0 0 12px rgba(45, 115, 231, 0.15);
            background-image: radial-gradient(circle at center, #1e56d7 0%, #6ad6f6 55%, #effaff 100%);
            position: relative;
          }
          .login-logo-core:before {
            content: '';
            position: absolute;
            inset: -10px;
            border-radius: 50%;
            border: 2px dashed #c4d8ff;
          }
          .login-logo-core:after {
            content: '✳';
            position: absolute;
            left: 50%;
            top: 50%;
            transform: translate(-50%, -50%);
            width: 88px;
            height: 88px;
            border-radius: 50%;
            background: linear-gradient(135deg, #2a60e6, #49bde6);
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: 900;
            box-shadow: inset 0 0 0 4px #fcfdff;
            opacity: 0.95;
          }
          .login-welcome {
            text-align: center;
            margin-bottom: 34px;
          }
          .login-welcome h1 {
            margin: 0 0 8px;
            font-size: clamp(34px, 3.4vw, 48px);
            line-height: 1;
            color: #17224b;
            font-weight: 900;
            letter-spacing: -0.04em;
          }
          .login-welcome p {
            margin: 0;
            font-size: 24px;
            color: #526a88;
            line-height: 1.35;
          }
          .login-form-wrap {
            width: 100%;
            display: flex;
            flex-direction: column;
            gap: 16px;
          }
          .login-input-group {
            display: flex;
            align-items: stretch;
            border: 1px solid #cbd5e1;
            border-radius: 12px;
            overflow: hidden;
            background-color: #fff;
            transition: all 0.2s ease-in-out;
            box-shadow: 0 1px 2px rgba(0,0,0,0.05);
          }
          .login-input-group:focus-within {
            border-color: #3b82f6 !important;
            box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15) !important;
          }
          .login-input-group .login-input-icon {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 46px;
            background-color: #eef7ff;
            color: #2f54eb;
            border-right: 1px solid #d6e9f7;
          }
          .login-input-group input {
            flex: 1;
            border: none;
            outline: none;
            padding: 0.82rem 1rem;
            font-size: 0.925rem;
            color: #0f172a;
            background-color: transparent;
          }
          .login-input-group .login-password-toggle {
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 0 1rem;
            cursor: pointer;
            color: #94a3b8;
          }
          .login-input-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            font-size: 13px;
            color: #536878;
            margin-bottom: 12px;
          }
          .login-remember {
            display: inline-flex;
            align-items: center;
            gap: 8px;
          }
          .login-remember input {
            accent-color: #2f54eb;
          }
          .login-forgot {
            color: #2a6eca;
            font-weight: 700;
          }
          .login-btn-primary {
            background: linear-gradient(135deg, #1d357f 0%, #34248b 100%);
            color: #fff;
            border: none;
            border-radius: 12px;
            font-weight: 800;
            padding: 0.86rem 1.5rem;
            width: 100%;
            transition: all 0.2s ease-in-out;
            cursor: pointer;
            box-shadow: 0 4px 10px rgba(47, 84, 235, 0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 12px;
          }
          .login-btn-primary:hover {
            background: linear-gradient(135deg, #13255a 0%, #261f7a 100%);
          }
          .login-btn-primary:disabled {
            background-color: #adc6ff;
            cursor: not-allowed;
          }
          .login-action-arrow {
            font-size: 26px;
            line-height: 1;
          }
          .login-divider {
            display: flex;
            align-items: center;
            gap: 12px;
            margin: 24px 0 12px;
            color: #526a88;
            font-weight: 700;
          }
          .login-divider:before,
          .login-divider:after {
            content: '';
            flex: 1;
            height: 1px;
            background: #bfd3ee;
          }
          .login-admin-btn {
            width: 100%;
            border-radius: 12px;
            border: 1px solid #2b64c3;
            background: transparent;
            color: #233d66;
            padding: 12px 20px;
            font-size: 15px;
            font-weight: 700;
            cursor: pointer;
          }
          .login-admin-btn .admin-icon {
            margin-right: 8px;
          }
          .login-footer-band {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            margin-top: 54px;
            color: #486976;
            font-size: 13px;
            font-weight: 700;
          }
          .login-footer-band .shield {
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, #2a59a1 0%, #7acef9 100%);
            display: flex;
            align-items: center;
            justify-content: center;
            color: #fff;
            font-size: 17px;
          }
          @media (max-width: 768px) {
            .login-right-panel-new {
              padding: 1rem;
            }
            .login-auth-shell {
              padding: 36px 24px;
              min-height: auto;
            }
            .login-logo-core {
              width: 118px;
              height: 118px;
            }
          }
        `}</style>

        <style>{`
          .login-container-new { display:grid; grid-template-columns:minmax(360px,.9fr) minmax(560px,1.1fr); background:#f7f9fc; }
          .login-container-new:before { width:520px; height:520px; left:auto; right:-220px; top:-220px; border:0; border-radius:50%; transform:none; background:radial-gradient(circle,rgba(59,130,246,.16),transparent 68%); }
          .login-container-new:after,.login-page-skyline { display:none; }
          .login-left-panel-new { position:relative; display:flex; flex-direction:column; justify-content:space-between; padding:clamp(36px,5vw,72px); color:#fff; background:linear-gradient(145deg,#071a45 0%,#123b91 55%,#2563eb 100%); isolation:isolate; overflow:hidden; }
          .login-left-panel-new:before,.login-left-panel-new:after { content:''; position:absolute; border:1px solid rgba(255,255,255,.12); border-radius:50%; z-index:-1; }
          .login-left-panel-new:before { width:520px; height:520px; left:-270px; bottom:-180px; }.login-left-panel-new:after { width:360px; height:360px; right:-170px; top:12%; }
          .login-brand { display:flex; align-items:center; gap:13px; font-weight:800; font-size:19px; }.login-brand-mark { width:44px; height:44px; border-radius:14px; display:grid; place-items:center; background:rgba(255,255,255,.14); border:1px solid rgba(255,255,255,.18); }
          .login-hero { max-width:510px; margin:auto 0; padding:70px 0; }.login-kicker { display:inline-flex; gap:8px; align-items:center; padding:7px 11px; border-radius:999px; background:rgba(255,255,255,.1); border:1px solid rgba(255,255,255,.14); font-size:12px; font-weight:700; letter-spacing:.06em; text-transform:uppercase; }
          .login-hero h2 { margin:24px 0 18px; font-size:clamp(38px,4.4vw,64px); line-height:1.04; letter-spacing:-.055em; font-weight:850; }.login-hero p { margin:0; max-width:460px; color:rgba(235,243,255,.78); font-size:17px; line-height:1.75; }
          .login-benefits { display:grid; gap:13px; margin-top:34px; }.login-benefit { display:flex; align-items:center; gap:11px; font-size:14px; color:rgba(255,255,255,.9); }.login-benefit-icon { width:23px; height:23px; border-radius:50%; display:grid; place-items:center; background:rgba(94,234,212,.16); color:#85f4df; font-size:10px; }.login-left-footer { color:rgba(255,255,255,.55); font-size:12px; }.login-dot-grid { position:absolute; right:40px; bottom:60px; width:110px; height:110px; opacity:.22; background-image:radial-gradient(#fff 1.5px,transparent 1.5px); background-size:14px 14px; z-index:-1; }
          .login-mobile-brand { display:none; }.login-right-panel-new { display:grid; place-items:center; padding:48px clamp(28px,7vw,110px); }.login-auth-shell { width:min(100%,470px); min-height:0; padding:0; background:transparent; border:0; border-radius:0; box-shadow:none; }.login-auth-shell:before,.login-auth-shell:after,.login-logo { display:none; }
          .login-welcome { text-align:left; margin-bottom:36px; }.login-welcome h1 { margin:0 0 12px; font-size:clamp(34px,3.2vw,46px); line-height:1.08; color:#0b1739; font-weight:850; letter-spacing:-.045em; }.login-welcome p { font-size:16px; color:#6b7894; line-height:1.6; }.login-form-wrap { gap:19px; }
          .login-field-label { display:block; margin-bottom:9px; color:#263451; font-size:13px; font-weight:750; }.login-field-meta { display:flex; align-items:center; justify-content:space-between; margin-bottom:9px; }.login-field-meta .login-field-label { margin:0; }.login-method-toggle { border:0; padding:0; background:none; color:#2563eb; cursor:pointer; font-size:12px; font-weight:750; }.login-method-toggle:hover,.login-forgot:hover { color:#1749b5; text-decoration:underline; }
          .login-input-group { min-height:56px; border-color:#d8dfeb; border-radius:14px; box-shadow:0 1px 2px rgba(16,24,40,.025); }.login-input-group:focus-within { border-color:#3975ed!important; box-shadow:0 0 0 4px rgba(59,130,246,.11)!important; }.login-input-group .login-input-icon { width:52px; color:#59708f; background:transparent; border:0; }.login-input-group input { min-width:0; padding:0 15px 0 2px; font-size:15px; color:#101c36; }.login-input-group input::placeholder { color:#9aa6ba; }.login-input-group .login-password-toggle { width:52px; padding:0; display:grid; place-items:center; border:0; background:transparent; }
          .login-input-row { margin:-1px 0 2px; color:#596781; }.login-remember { cursor:pointer; }.login-remember input { width:16px; height:16px; accent-color:#2563eb; }.login-forgot { color:#2563eb; font-weight:750; cursor:pointer; }.login-btn-primary { min-height:56px; padding:0 24px; border-radius:14px; font-size:15px; background:linear-gradient(110deg,#174eb5,#2563eb 60%,#397ef6); box-shadow:0 12px 24px rgba(37,99,235,.23); }.login-btn-primary:hover { transform:translateY(-1px); background:linear-gradient(110deg,#174eb5,#2563eb 60%,#397ef6); box-shadow:0 15px 28px rgba(37,99,235,.29); }.login-btn-primary:disabled { opacity:.65; transform:none; }.login-footer-band { gap:8px; margin-top:35px; color:#8490a6; font-size:11px; font-weight:650; }.login-footer-band .shield { width:auto; height:auto; background:none; color:#2f73df; font-size:inherit; }
          @media(max-width:980px) { .login-container-new{grid-template-columns:1fr}.login-left-panel-new{display:none}.login-right-panel-new{padding:42px 24px}.login-mobile-brand{display:flex;align-items:center;gap:10px;margin-bottom:64px;color:#123b85;font-weight:850}.login-mobile-brand .login-brand-mark{width:40px;height:40px;background:#e9f1ff;border-color:#d8e6ff} }
          @media(max-width:768px) { .login-right-panel-new{place-items:start center;padding:28px 22px 24px}.login-auth-shell{padding:0}.login-mobile-brand{margin-bottom:52px}.login-welcome{margin-bottom:30px}.login-welcome h1{font-size:35px} }
        `}</style>

        <section className="login-left-panel-new" aria-label="Institute platform introduction">
          <div className="login-brand"><span className="login-brand-mark"><FaGraduationCap size={22} /></span><span>Institute Portal</span></div>
          <div className="login-hero"><span className="login-kicker"><FaShieldAlt /> One secure workspace</span><h2>Learning made simpler, every day.</h2><p>Access classes, attendance, assignments, updates and everything that keeps your institute connected.</p><div className="login-benefits"><div className="login-benefit"><span className="login-benefit-icon"><FaCheck /></span>Fast access to your academic dashboard</div><div className="login-benefit"><span className="login-benefit-icon"><FaCheck /></span>Secure and reliable account protection</div><div className="login-benefit"><span className="login-benefit-icon"><FaCheck /></span>Designed for students, staff and families</div></div></div>
          <div className="login-left-footer">© {new Date().getFullYear()} Institute Management System</div><div className="login-dot-grid" />
        </section>

        <div className="login-right-panel-new">
          <div className="login-auth-shell">
            <div className="login-mobile-brand"><span className="login-brand-mark"><FaGraduationCap size={20} /></span><span>Institute Portal</span></div>
            <div className="login-logo">
              <div className="login-logo-core" aria-hidden="true" />
            </div>

            <div className="login-welcome">
              <h1>Welcome back</h1>
              <p>Enter your details to securely access your account.</p>
            </div>

            <div className="login-form-wrap">
              <div>
                <label className="login-field-label" htmlFor="email">Email or mobile number</label>
                <div className={`login-input-group ${emailError ? 'error' : ''}`} style={emailError ? { borderColor: '#ef4444' } : {}}>
                  <div className="login-input-icon">
                    <FaUserAlt size={14} />
                  </div>
                  <input
                    id="email"
                    type="text"
                    placeholder="Mobile Number / Username"
                    value={email}
                    onChange={handleChange}
                    onKeyDown={loginEnter}
                  />
                </div>
                {emailError && (
                  <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '0.35rem', textAlign: 'left', fontWeight: 500 }}>
                    {emailError}
                  </div>
                )}
              </div>

              <div>
                <div className="login-field-meta"><label className="login-field-label" htmlFor="pswrd">{loginMethod === 'otp' ? 'One-time password' : 'Password'}</label><button type="button" className="login-method-toggle" onClick={() => setLoginMethod(loginMethod === 'password' ? 'otp' : 'password')}>{loginMethod === 'password' ? 'Use OTP instead' : 'Use password instead'}</button></div>
                <div className={`login-input-group ${passwordError ? 'error' : ''}`} style={passwordError ? { borderColor: '#ef4444' } : {}}>
                  <div className="login-input-icon">
                    <FaLock size={14} />
                  </div>
                  <input
                    id="pswrd"
                    type={loginMethod === 'otp' ? 'text' : (showPassword ? 'password' : 'text')}
                    placeholder={loginMethod === 'otp' ? 'Enter OTP' : 'Password'}
                    value={password}
                    onChange={handleChange}
                    onKeyDown={loginEnter}
                  />
                  {loginMethod === 'password' && (
                    <div className="login-password-toggle" onClick={showHidePassword}>
                      {showPassword ? <FaEyeSlash size={16} /> : <FaEye size={16} />}
                    </div>
                  )}
                </div>
                <div style={{ display: 'none' }}>
                  <span 
                    style={{ fontSize: 12, color: '#2a6eca', cursor: 'pointer', fontWeight: 600 }}
                    onClick={() => setLoginMethod(loginMethod === 'password' ? 'otp' : 'password')}
                  >
                    {loginMethod === 'password' ? 'Login with OTP' : 'Login with Password'}
                  </span>
                </div>
                {passwordError && (
                  <div style={{ color: '#ef4444', fontSize: '0.78rem', marginTop: '0.35rem', textAlign: 'left', fontWeight: 500 }}>
                    {passwordError}
                  </div>
                )}
              </div>

              <div className="login-input-row">
                <label className="login-remember">
                  <input type="checkbox" />
                  Remember me
                </label>
                <span className="login-forgot">Forgot Password?</span>
              </div>

              <button className="login-btn-primary" onClick={handleSubmit} disabled={isLoading}>
                <span>{isLoading ? 'Logging In...' : 'Login'}</span>
                <span className="login-action-arrow">→</span>
              </button>

              {/* <div className="login-divider"><span>OR</span></div> */}

              {/* <button className="login-admin-btn">
                <span className="admin-icon"><FaUniversity size={14} /></span>
                Login as Admin
              </button> */}
            </div>

            <div className="login-footer-band">
              <span className="shield">♢</span>
              <span>Secure · Reliable · Smart institute management</span>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

export default Login;
